23	  <svg viewBox="0 0 200 200" xmlns="http://www.w3.org/2000/svg">
24	    <rect width="200" height="200" fill="#050810"></rect>
25	    <rect x="60" y="55" width="80" height="80" rx="18" fill="url(#ng)"></rect>
26	    <text x="100" y="112" text-anchor="middle" fill="#fff" font-family="sans-serif" font-weight="800" font-size="52">N</text>
27	    <text x="100" y="155" text-anchor="middle" fill="#60a5fa" font-family="sans-serif" font-weight="700" font-size="14" letter-spacing="3">NEUROSPECT</text>
28	    <defs><linearGradient id="ng" x1="0" y1="0" x2="1" y2="1"><stop offset="0%" stop-color="#3b82f6"></stop><stop offset="100%" stop-color="#1d4ed8"></stop></linearGradient></defs>
