33	  <script>
34	    
35	document.addEventListener('DOMContentLoaded', async function() {
36	  const loading = document.getElementById('__bundler_loading');
37	  function setStatus(msg) { if (loading) loading.textContent = msg; }
38	
39	  // Error sink persists across replaceWith since it's on window, not the DOM.
40	  window.addEventListener('error', function(e) {
41	    var p = document.body || document.documentElement;
42	    var d = document.getElementById('__bundler_err') || p.appendChild(document.createElement('div'));
43	    d.id = '__bundler_err';
44	    d.style.cssText = 'position:fixed;bottom:12px;left:12px;right:12px;font:12px/1.4 ui-monospace,monospace;background:#2a1215;color:#ff8a80;padding:10px 14px;border-radius:8px;border:1px solid #5c2b2e;z-index:99999;white-space:pre-wrap;max-height:40vh;overflow:auto';
45	    d.textContent = (d.textContent ? d.textContent + String.fromCharCode(10) : '') +
46	      '[bundle] ' + (e.message || e.type) +
47	      (e.filename ? ' (' + e.filename.slice(0, 60) + ':' + e.lineno + ')' : '');
48	  }, true);
49	
50	  try {
51	    const manifestEl = document.querySelector('script[type="__bundler/manifest"]');
52	    const templateEl = document.querySelector('script[type="__bundler/template"]');
53	    if (!manifestEl || !templateEl) {
54	      setStatus('Error: missing bundle data');
55	      console.error('[bundler] Missing script tags — manifestEl:', !!manifestEl, 'templateEl:', !!templateEl);
56	      return;
57	    }
58	
59	    const manifest = JSON.parse(manifestEl.textContent);
60	    let template = JSON.parse(templateEl.textContent);
61	
62	    const uuids = Object.keys(manifest);
63	    setStatus('Unpacking ' + uuids.length + ' assets...');
64	
65	    const blobUrls = {};
66	    await Promise.all(uuids.map(async (uuid) => {
67	      const entry = manifest[uuid];
68	      try {
69	        const binaryStr = atob(entry.data);
70	        const bytes = new Uint8Array(binaryStr.length);
71	        for (let i = 0; i < binaryStr.length; i++) bytes[i] = binaryStr.charCodeAt(i);
72	
73	        let finalBytes = bytes;
74	        if (entry.compressed) {
75	          if (typeof DecompressionStream !== 'undefined') {
76	            const ds = new DecompressionStream('gzip');
77	            const writer = ds.writable.getWriter();
78	            const reader = ds.readable.getReader();
79	            writer.write(bytes);
80	            writer.close();
81	            const chunks = [];
82	            let totalLen = 0;
83	            while (true) {
84	              const { done, value } = await reader.read();
85	              if (done) break;
86	              chunks.push(value);
87	              totalLen += value.length;
88	            }
89	            finalBytes = new Uint8Array(totalLen);
90	            let offset = 0;
91	            for (const chunk of chunks) { finalBytes.set(chunk, offset); offset += chunk.length; }
92	          } else {
93	            console.warn('DecompressionStream not available, asset ' + uuid + ' may not render');
94	          }
95	        }
96	
97	        blobUrls[uuid] = URL.createObjectURL(new Blob([finalBytes], { type: entry.mime }));
98	      } catch (err) {
99	        console.error('Failed to decode asset ' + uuid + ':', err);
100	        blobUrls[uuid] = URL.createObjectURL(new Blob([], { type: entry.mime }));

1	/* Flagship Simulator Section */
2	const { useState, useEffect, useRef, useCallback, useMemo } = React;
