4	/* ── Candle Chart SVG ── */
5	function SimChart({ candles, visibleCount, tierEntries, width = 700, height = 260 }) {
6	  const pad = { t: 12, r: 48, b: 20, l: 12 };
7	  const cw = (width - pad.l - pad.r) / candles.length;
8	  const visible = candles.slice(0, visibleCount);
9	  const allP = candles.flatMap(c => [c.h, c.l]);
10	  const minP = Math.min(...allP) - 5; const maxP = Math.max(...allP) + 5;
11	  const range = maxP - minP;
12	  const y = p => pad.t + ((maxP - p) / range) * (height - pad.t - pad.b);
13	  const x = i => pad.l + i * cw;
14	
15	  // FVG zones
16	  const fvgs = [
17	    { y1: 18355, y2: 18310, label: 'FVG', color: 'rgba(6,182,212,0.06)' },
18	    { y1: 18420, y2: 18395, label: 'OB', color: 'rgba(139,92,246,0.05)' },
19	  ];
20	
21	  // Price scale ticks
22	  const ticks = [];
23	  const step = Math.ceil(range / 5 / 10) * 10;
24	  for (let p = Math.ceil(minP / step) * step; p <= maxP; p += step) ticks.push(p);
25	
26	  return (
27	    <svg viewBox={`0 0 ${width} ${height}`} style={{ width: '100%', height: '100%' }}>
28	      {/* Grid */}
29	      {ticks.map(p => (
30	        <g key={p}>
31	          <line x1={pad.l} x2={width - pad.r} y1={y(p)} y2={y(p)} stroke="rgba(255,255,255,0.04)" strokeWidth="0.5" />
32	          <text x={width - pad.r + 4} y={y(p) + 3} fill="rgba(255,255,255,0.2)" fontSize="8" fontFamily="var(--font-mono)">{p.toLocaleString()}</text>
33	        </g>
34	      ))}
35	      {/* FVG zones */}
36	      {fvgs.map((f, i) => (
37	        <g key={i}>
38	          <rect x={pad.l} y={y(f.y1)} width={width - pad.l - pad.r} height={y(f.y2) - y(f.y1)} fill={f.color} rx="2" />
39	          <text x={pad.l + 4} y={y(f.y1) + 10} fill="rgba(6,182,212,0.25)" fontSize="7" fontFamily="var(--font-mono)">{f.label}</text>
40	        </g>
41	      ))}
42	      {/* Candles */}
43	      {visible.map((c, i) => {
44	        const bull = c.c >= c.o;
45	        const color = bull ? '#10b981' : '#ef4444';
46	        const bx = x(i) + cw * 0.2;
47	        const bw = cw * 0.6;
48	        const bodyTop = y(Math.max(c.o, c.c));
49	        const bodyH = Math.max(y(Math.min(c.o, c.c)) - bodyTop, 1);
50	        return (
51	          <g key={i} style={{ animation: `fade-in 0.3s ${i * 60}ms both` }}>
52	            <line x1={x(i) + cw / 2} x2={x(i) + cw / 2} y1={y(c.h)} y2={y(c.l)} stroke={color} strokeWidth="1" strokeOpacity="0.5" />
53	            <rect x={bx} y={bodyTop} width={bw} height={bodyH} fill={color} fillOpacity={0.8} rx="0.5" />
54	          </g>
55	        );
56	      })}
57	      {/* Tier entry markers */}
58	      {tierEntries.filter(e => e.candle < visibleCount).map((e, i) => (
59	        <g key={i}>
60	          <line x1={x(e.candle) + cw / 2} x2={x(e.candle) + cw / 2} y1={y(e.price) - 12} y2={y(e.price)} stroke={e.color} strokeWidth="1" strokeDasharray="2 2" strokeOpacity="0.5" />
61	          <circle cx={x(e.candle) + cw / 2} cy={y(e.price)} r="3.5" fill={e.color} fillOpacity="0.9">
62	            <animate attributeName="r" values="3;4;3" dur="2s" repeatCount="indefinite" />
63	          </circle>
64	          <text x={x(e.candle) + cw / 2} y={y(e.price) - 15} fill={e.color} fontSize="6" fontFamily="var(--font-mono)" textAnchor="middle" opacity="0.7">{e.tier}</text>
65	        </g>
66	      ))}
67	      {/* Crosshair line at last candle */}
68	      {visibleCount > 0 && (
69	        <line x1={x(visibleCount - 1) + cw / 2} x2={width - pad.r} y1={y(visible[visibleCount - 1]?.c || 0)} y2={y(visible[visibleCount - 1]?.c || 0)} stroke="rgba(255,255,255,0.15)" strokeWidth="0.5" strokeDasharray="3 3" />
70	      )}
71	    </svg>
72	  );
73	}
