75	/* ── Tier Reasoning Card ── */
76	function TierCard({ tier, meta, isActive, pnl, trades, winRate, reasoning, status }) {
77	  const color = meta.color;
78	  return (
79	    <div style={{
80	      background: isActive ? `rgba(${meta.rgb},0.06)` : 'rgba(255,255,255,0.02)',
81	      border: `1px solid ${isActive ? `rgba(${meta.rgb},0.25)` : 'rgba(255,255,255,0.04)'}`,
82	      borderRadius: 10, padding: '0.75rem', transition: 'all 0.4s',
83	      borderLeft: `3px solid ${color}`,
84	    }}>
85	      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: '0.375rem' }}>
86	        <div style={{ display: 'flex', alignItems: 'center', gap: '0.375rem' }}>
