92	          color: status === 'Trading' ? '#34d399' : status === 'Skipped' ? '#64748b' : 'var(--text-muted)' }}>
93	          {status}
94	        </span>
95	      </div>
96	      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr 1fr', gap: '0.5rem', marginBottom: '0.5rem' }}>
97	        <div>
98	          <div style={{ fontFamily: 'var(--font-mono)', fontSize: '0.5625rem', color: 'var(--text-dim)', textTransform: 'uppercase' }}>P&L</div>
99	          <div style={{ fontFamily: 'var(--font-mono)', fontSize: '0.8125rem', fontWeight: 600, color: pnl >= 0 ? '#34d399' : '#f87171' }}>
100	            {pnl >= 0 ? '+' : ''}{typeof pnl === 'number' ? `$${pnl.toLocaleString()}` : pnl}
101	          </div>
102	        </div>
103	        <div>
104	          <div style={{ fontFamily: 'var(--font-mono)', fontSize: '0.5625rem', color: 'var(--text-dim)', textTransform: 'uppercase' }}>Trades</div>
105	          <div style={{ fontFamily: 'var(--font-mono)', fontSize: '0.8125rem', fontWeight: 600, color: '#fff' }}>{trades}</div>
106	        </div>
107	        <div>
108	          <div style={{ fontFamily: 'var(--font-mono)', fontSize: '0.5625rem', color: 'var(--text-dim)', textTransform: 'uppercase' }}>Win Rate</div>
109	          <div style={{ fontFamily: 'var(--font-mono)', fontSize: '0.8125rem', fontWeight: 600, color: '#fff' }}>{winRate}</div>
110	        </div>
111	      </div>
112	      {reasoning && (
113	        <div style={{ fontSize: '0.6875rem', color: 'var(--text-muted)', lineHeight: 1.5, borderTop: '1px solid rgba(255,255,255,0.04)', paddingTop: '0.375rem' }}>
114	          {reasoning}
115	        </div>
116	      )}
117	    </div>
118	  );
119	}
120	
121	/* ── Trade Log Row ── */
122	function TradeLogRow({ time, tier, action, entry, result, pnl, delay = 0 }) {
123	  return (
124	    <div style={{ display: 'grid', gridTemplateColumns: '60px 80px 1fr 60px 60px', gap: '0.5rem', padding: '0.375rem 0.5rem', fontSize: '0.6875rem', fontFamily: 'var(--font-mono)', borderBottom: '1px solid rgba(255,255,255,0.03)', animation: `fade-in 0.4s ${delay}ms both` }}>
125	      <span style={{ color: 'var(--text-dim)' }}>{time}</span>
126	      <span style={{ color: TIER_META[tier]?.color || '#fff' }}>{TIER_META[tier]?.short || tier}</span>
127	      <span style={{ color: 'var(--text-secondary)' }}>{action}</span>
128	      <span style={{ color: '#fff' }}>{entry}</span>
129	      <span style={{ color: pnl >= 0 ? '#34d399' : '#f87171', textAlign: 'right' }}>{pnl >= 0 ? '+' : ''}{pnl}</span>
130	    </div>
131	  );
132	}
