134	/* ── Main Simulator ── */
135	function SimulatorSection() {
136	  const [running, setRunning] = useState(false);
137	  const [candleIdx, setCandleIdx] = useState(0);
138	  const [speed, setSpeed] = useState(1);
139	  const intervalRef = useRef(null);
140	
141	  const totalCandles = NQ_CANDLES.length;
142	
143	  const startSim = () => {
144	    setRunning(true);
145	    setCandleIdx(0);
146	  };
147	
148	  useEffect(() => {
149	    if (!running) return;
150	    if (candleIdx >= totalCandles) { setRunning(false); return; }
151	    const ms = [800, 400, 160][speed - 1] || 800;
152	    intervalRef.current = setTimeout(() => setCandleIdx(c => c + 1), ms);
153	    return () => clearTimeout(intervalRef.current);
154	  }, [running, candleIdx, speed]);
155	
156	  const visibleCount = running || candleIdx > 0 ? candleIdx : totalCandles;
157	
