180	  ];
181	
182	  const tradeLog = [
183	    { time: '10:02', tier: 'tier1', action: 'SHORT entry', entry: '18,295', pnl: -280 },
184	    { time: '10:05', tier: 'tier3', action: 'SHORT entry', entry: '18,305', pnl: 480 },
185	    { time: '10:05', tier: 'tier4', action: 'SHORT entry', entry: '18,300', pnl: 560 },
186	    { time: '10:32', tier: 'tier1', action: 'LONG entry', entry: '18,390', pnl: 800 },
187	    { time: '10:34', tier: 'tier2', action: 'LONG entry', entry: '18,385', pnl: 460 },
188	    { time: '11:15', tier: 'tier4', action: 'LONG entry', entry: '18,420', pnl: 700 },
