190	  const visibleLogs = tradeLog.filter((_, i) => progress > (i + 1) / (tradeLog.length + 2));
191	
192	  return (
193	    <section id="simulator" className="section" style={{ paddingTop: '4rem', paddingBottom: '4rem' }}>
