198	          <h2>Watch Four Traders. Same Market. Different Tools.</h2>
199	          <p className="section-sub">See how the same NQ session plays out across a discretionary trader, quant trader, hybrid trader, and sovereign architect.</p>
200	        </Reveal>
201	        <Reveal delay={100}>
202	          <div className="neon-card neon-card-cyan" style={{ padding: 0, overflow: 'hidden', background: 'rgba(8,10,18,0.95)' }}>
203	            {/* Toolbar */}
204	            <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: '0.75rem 1rem', borderBottom: '1px solid rgba(255,255,255,0.04)', flexWrap: 'wrap', gap: '0.5rem' }}>
