"""Phase 0 acceptance: Live Trading Simulator data structure validation.

Phase 0 spec: "Live trading simulator (/simulator)" with 4 trader tiers.
EdgeLab spec: "3 interactive engines" validated via content check on ns-performance.jsx.
"""
import re
from pathlib import Path

UI_DIR = Path(__file__).parent.parent.parent / "neurospect-ui"
SIMULATOR_FILE = UI_DIR / "ns-simulator.jsx"
DATA_FILE = UI_DIR / "ns-data.js"
PERFORMANCE_FILE = UI_DIR / "ns-performance.jsx"

EXPECTED_TIER_IDS = {"tier1", "tier2", "tier3", "tier4"}


def _read(path: Path) -> str:
    return path.read_text(encoding="utf-8")


def test_simulator_file_exists():
    assert SIMULATOR_FILE.exists()


def test_data_file_exists():
    assert DATA_FILE.exists()


def test_four_trader_tiers_in_simulator():
    content = _read(SIMULATOR_FILE)
    for tid in EXPECTED_TIER_IDS:
        assert f"'{tid}'" in content or f'"{tid}"' in content, (
            f"Tier '{tid}' not found in ns-simulator.jsx"
        )


def test_four_trader_tiers_in_data():
    content = _read(DATA_FILE)
    for tid in EXPECTED_TIER_IDS:
        assert tid in content, f"Tier '{tid}' not found in ns-data.js"


def test_seven_prescripted_tier_entries():
    """7 pre-scripted candle/price entry events drive the live simulation."""
    content = _read(SIMULATOR_FILE)
    # Each entry: { candle: N, price: N, tier: '...', color: '...' }
    entries = re.findall(r"\{\s*candle:\s*\d+,\s*price:\s*\d+,\s*tier:", content)
    assert len(entries) == 7, f"Expected 7 tier entries, found {len(entries)}"


def test_candle_data_present():
    content = _read(DATA_FILE)
    assert "NQ_CANDLES" in content or "candles" in content.lower()


def test_equity_curves_for_all_tiers():
    content = _read(DATA_FILE)
    # Each tier has 20 equity data points
    assert "equity" in content.lower() or "balance" in content.lower()
    for tid in EXPECTED_TIER_IDS:
        assert tid in content


def test_tier_kpis_defined():
    content = _read(DATA_FILE)
    # KPI fields: winRate, pnl, profitFactor, sharpe
    for kpi in ("winRate", "pnl", "profitFactor", "sharpe"):
        assert kpi in content, f"KPI '{kpi}' not in ns-data.js"


def test_session_data_defined():
    content = _read(DATA_FILE)
    # Session data for each tier (asia, london, ny_am, ny_pm, ny_lunch)
    assert "london" in content.lower() or "london" in content
    assert "ny" in content.lower()


# --- EdgeLab Research Studio ---

def test_performance_file_exists():
    assert PERFORMANCE_FILE.exists()


def test_edgelab_feature_discovery_engine():
    content = _read(PERFORMANCE_FILE)
    assert "feature" in content.lower() and (
        "discover" in content.lower() or "engine" in content.lower()
    )


def test_edgelab_regime_optimization_engine():
    content = _read(PERFORMANCE_FILE)
    assert "regime" in content.lower() or "optim" in content.lower()


def test_edgelab_nslm_engine():
    content = _read(PERFORMANCE_FILE)
    assert "nslm" in content.lower() or "NSLM" in content

